import{_ as a,a as n}from"./chunks/basic-information.Cz6Sp50G.js";import{_ as s,m as i,k as d,ah as o,q as e}from"./chunks/framework.HEc25T99.js";const y=JSON.parse('{"title":"Platform Identity","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"developers/admin-panel/content-management/platform-identity.md","filePath":"src/en/developers/admin-panel/content-management/platform-identity.md"}'),r={name:"developers/admin-panel/content-management/platform-identity.md"},c=a+"#light-only",l=n+"#dark-only";function p(h,t,m,u,f,g){return d(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="platform-identity" tabindex="-1">Platform Identity <a class="header-anchor" href="#platform-identity" aria-label="Permalink to &quot;Platform Identity&quot;">​</a></h1><p>This page gathers the site&#39;s global information — the values consumed in templates through <code>getAppInformationValue()</code> (see <a href="./../../development/utilities.html#usecontent">Utilities</a>) rather than defined in a section&#39;s data structure. It has three tabs: <strong>Basic information</strong>, <strong>Branding</strong>, and <strong>Social networks</strong>.</p><h2 id="basic-information" tabindex="-1">Basic information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic information&quot;">​</a></h2>',3),e("p",null,[e("img",{src:c,alt:"Basic information"}),e("img",{src:l,alt:"Basic information"})],-1),o(`<table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Website name</td><td>Displayed name of the platform (<code>name</code> key).</td></tr><tr><td>Email</td><td>Main contact email address (<code>email</code> key).</td></tr><tr><td>Phone</td><td>Main contact phone number (<code>phone</code> key).</td></tr><tr><td>Address</td><td>Physical address (<code>address</code> key).</td></tr><tr><td>Postal code</td><td>Associated postal code (<code>postalCode</code> key).</td></tr><tr><td>Description</td><td>Short site presentation, translatable per language through the selector above the field (<code>description</code> key).</td></tr></tbody></table><h2 id="branding" tabindex="-1">Branding <a class="header-anchor" href="#branding" aria-label="Permalink to &quot;Branding&quot;">​</a></h2><p>Tab dedicated to brand media and colors: logo, one-color logo, icon/favicon, one-color icon, and primary, secondary and accent colors (<code>logo</code>, <code>oneColorLogo</code>, <code>icon</code>, <code>oneColorIcon</code>, <code>primaryColor</code>, <code>secondaryColor</code>, <code>accentColor</code> keys). These values feed <code>appPrimaryColor</code>/<code>appSecondaryColor</code>/<code>appAccentColor</code>/<code>logo</code>/<code>icon</code> on the <code>useContent()</code> side.</p><h2 id="social-networks" tabindex="-1">Social networks <a class="header-anchor" href="#social-networks" aria-label="Permalink to &quot;Social networks&quot;">​</a></h2><p>One URL field per supported social network — only fill in the networks actually used by the site, an empty field does not display the corresponding icon in the Header/Footer:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>facebook, twitter, instagram, whatsapp, linkedin, youtube, pinterest, snapchat,</span></span>
<span class="line"><span>tiktok, telegram, discord, reddit, tumblr, vimeo, twitch, github, dribbble,</span></span>
<span class="line"><span>behance, medium, stackOverflow, threads, messenger, playstore, appstore</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">For developers</p><p>These values can also be set from the command line through <a href="./../../resources/cli.html#creopse-base-info-alias-info"><code>creopse base-info update</code></a> — useful for populating them automatically while integrating a template rather than going through this page manually.</p></div><div class="tip custom-block"><p class="custom-block-title">See also</p><p>An end-user–oriented version of this section exists in the <a href="./../../../users/sections/content-management.html">User Guide</a>.</p></div>`,8)])])}const k=s(r,[["render",p]]);export{y as __pageData,k as default};
